function similarUpsets(f){const u=upsetInfo(f);if(!u.market||u.p===null)return '<div class="similarbox"><h3>What happened in similar games?</h3><p>A posted sportsbook underdog is needed to make this comparison. Pick’em and model-only underdogs are not mixed into the historical sportsbook records.</p></div>';const b=upsetBand(u.p),flags=currentFlags(f),matched=U.patterns.filter(r=>r.n&&r.keys.every(k=>flags.includes(k))).sort((a,b)=>b.keys.length-a.keys.length||b.n-a.n);return `<div class="similarbox"><span class="eyebrow">HISTORY BEHIND THE METER</span><h3>Underdogs with a ${b.label} chance</h3><div class="cohortscore">${upsetRecord(b)} <small>historical record</small></div><p>${b.n?`They won <b>${b.wins} of ${b.n}</b> games (${pct(b.rate)}). The model expected about ${fmt(b.expected)} wins.`:'No games fell in this range in our test.'}</p><p class="tiny">${sampleNote(b)}. Similar chance does not mean identical teams or circumstances. This record does not replace today’s ${pct(u.p)} estimate.</p>${b.n?cohortGames(b):''}${matched.length?`<details class="technical"><summary>Matching situations for this game</summary>${matched.map(patternCard).join('')}</details>`:'<p class="tiny">No tested situational group matches this game with recorded results.</p>'}<p class="tiny">Past-game replay · archived closing spreads · Sep 26–Oct 17, 2026 (ET). Not live-issued picks.</p></div>`}
function upsetHistory(){const perfect=U.patterns.filter(r=>r.n>=5&&r.losses===0),tiny=U.patterns.filter(r=>r.n>0&&r.n<5&&r.losses===0);$('upsetHistory').innerHTML=`<div class="eyebrow">DOES THE UPSET METER HOLD UP?</div><h2>How often did the underdogs actually win?</h2><p>${U.rows.length} past games with ESPN-reported closing spreads, out of ${U.testedGames} tested games. Each game appears once per probability range. A win means winning the game outright.</p><div class="notice"><b>${perfect.length?`${perfect.length} undefeated situations with at least five games`:'No undefeated situations with five or more games'}</b><p>We checked ${U.patterns.length} fixed situations: four individual factors and their six two-factor combinations. ${tiny.length?tiny.map(r=>`${esc(r.label)} was ${upsetRecord(r)}—only ${r.n} game${r.n===1?'':'s'}.`).join(' '):''} An undefeated past record is never a guaranteed future win.</p></div><div class="tablewrap"><table class="upsetbands"><thead><tr><th>Upset meter range</th><th>Underdog record</th><th>Actual win rate</th><th>Model expected</th></tr></thead><tbody>${U.bands.map(b=>`<tr><td>${b.label}</td><td>${upsetRecord(b)} <small>(${b.n} games)</small></td><td>${b.n?pct(b.rate):'No games'}</td><td>${b.n?fmt(b.expected)+' wins':'—'}</td></tr>`).join('')}</tbody></table></div><p class="tiny">Ranges include the lower boundary and exclude the upper boundary; the last includes 100%. Above 50% means the model favored the sportsbook underdog. Empty ranges are not evidence.</p><details class="technical"><summary>Explore all ${U.patterns.length} situations and their games</summary><div class="patterngrid">${U.patterns.map(patternCard).join('')}</div></details><details class="technical"><summary>How to read this evidence</summary><p>Earlier games are before October 11 UTC; later games are on or after that date. We show both periods for every situation, including losing records. No situation was independently validated on a new season, and overlapping groups are not independent evidence.</p><p>“Big win” means beating an opponent rated at least 1600 before the game—not necessarily a ranked opponent. “Stronger opponent coming up” means an opponent rated over 100 points higher within 14 days. Successful-play advantage compares offense minus defense success rates before the game. Home excludes neutral sites.</p><p>Historical probabilities use the main model’s earlier-date fit and uncertainty estimate at each test date. Current forecasts use a later fit and an updated uncertainty estimate, so this is an exploratory comparison, not a calibrated replacement probability. Injuries, QB experience and ranked-opponent/night combinations are not tested here.</p><p>Source: ESPN game summaries, explicitly labeled home and away closing lines. These archives were retrieved after the games; forecasts are reconstructions, not published pregame picks. ${U.excluded.length} games excluded for missing closing spreads or pick’em. Historical patterns do not change the scores or upset meter.</p></details>`}

function pickText(g,margin,actual=false){if(Math.abs(margin)<.000001)return actual?'Finished tied':'Too close to call';const team=name(margin>0?g.home:g.away),points=Math.abs(margin),amount=actual?fmt(points,0):(points<1?'less than 1':`about ${Math.round(points)}`);return `${team} ${actual?'won':'to win'} by ${amount} ${actual&&points===1?'point':'points'}`}
function validation(){upsetHistory();const n=M.heldout.length,wins=M.heldout.filter(r=>r.core[0]!==0&&Math.sign(r.core[0])===Math.sign(r.actual[0])).length;
