// Charts use the same saved forecasts and market snapshots as the game reports.
const DarkhorseCharts=(()=>{
 let selected=null,scope='all';
 const ns='http://www.w3.org/2000/svg';
 function openGame(id){$('matchConference').value='all';fillGames();show(id);tab('lab');document.querySelector('nav').scrollIntoView({behavior:'smooth',block:'start'});}
 function selection(f){selected=f.id;const g=game(f),u=upsetInfo(f),q=forecast(f);$('dhSelection').innerHTML=`<div class="eyebrow">${u.home&&!g.neutral?'HOME UNDERDOG':'UNDERDOG WATCH'}</div><div class="dh-logo-row">${logo(g.away)}<span>at</span>${logo(g.home)}</div><h3>${esc(name(u.team))}</h3><div class="dh-chance">${pct(u.p)}</div><small>chance to win the game outright</small><p>${esc(name(g.away))} at ${esc(name(g.home))}<br>${esc(date(g))}</p><p>Sportsbook: ${esc(line(g))}<br>Model: ${esc(name(g.away))} ${q.a} · ${esc(name(g.home))} ${q.h}</p><button type="button" id="dhOpenGame">Explore this matchup ↗</button>`;$('dhOpenGame').onclick=()=>openGame(f.id);document.querySelectorAll('.dh-dot').forEach(e=>e.classList.toggle('selected',e.dataset.id===f.id));}
 function radar(fs){
  if(!$('dhRadarPlot'))return;
  const all=fs.filter(f=>upsetInfo(f).market),rows=all.filter(f=>scope!=='home'||(upsetInfo(f).home&&!game(f).neutral));
