def stamp(): return dt.datetime.now(dt.timezone.utc).isoformat()
def date(s):return dt.datetime.fromisoformat(s.replace('Z','+00:00'))
def result(g,t):return g['hs']-g['as'] if g['home']==t else g['as']-g['hs']
